import React, { useState } from 'react';

// Define the FormField interface here
interface FormField {
  name: string;
  label: string;
  type: string;
}

// Create the Form component here
function Form() {
  // Create formFields array and call useForm here
  const formFields: FormField[] = [
    { name: 'username', label: 'Username', type: 'text' },
    { name: 'email', label: 'Email', type: 'email' },
  ];
  const { formValues, handleChange, handleSubmit } = useForm();

  return (
    <div>
      {/* Map through formFields to render InputField components and add a submit button */}
    </div>
  );
}

// Create the useForm hook here
function useForm() {
  // Initialize formValues state here
  const [formValues, setFormValues] = useState({});

  // Create the handleChange function here
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormValues({ ...formValues, [name]: value });
  };

  // Create the handleSubmit function here
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    console.log('Form submitted:', formValues);
  };

  // Return values from useForm hook here
  return { formValues, handleChange, handleSubmit };
}

// Create the InputField component here
function InputField({ name, label, type }: { name: string; label: string; type: string }) {
  // Return JSX structure here
  return (
    <div>
      <label htmlFor={name}>{label}</label>
      <input id={name} name={name} type={type} />
    </div>
  );
}
